        const c = await shell.exec(s.cond, io);
        const go = s.type === 'while' ? c === 0 : c !== 0;
        if (!go) break;
        try { status = await execStatements(shell, s.body, io); }
        catch (e) {
          if (e.loopCtl === 'break') break;
          if (e.loopCtl === 'continue') continue;
          throw e;
        }
